using NUnit.Framework;
using System.Collections.Generic;

[TestFixture]
public class CountLetterFrequencyTests
{
    [Test]
    public void Counts_Letters_Ignoring_Case()
    {
        var result = CountLetterFrequency("Anna");

        Assert.That(result['a'], Is.EqualTo(2));
        Assert.That(result['n'], Is.EqualTo(2));
    }

    private Dictionary<char, int> CountLetterFrequency(string name)
    {
        var counts = new Dictionary<char, int>();

        foreach (var ch in name.ToLowerInvariant())
        {
            if (!char.IsLetter(ch))
                continue;

            counts[ch] = counts.GetValueOrDefault(ch) + 1;
        }

        return counts;
    }
}
